 function spinPrompt(){const next=randomOrreryRecipe(prompt.id,promptFilters)||randomOrreryRecipe(prompt.id)||prompt;const merged={...next,genre:promptLocks.genre?prompt.genre:next.genre,object:promptLocks.object?prompt.object:next.object,twist:promptLocks.twist?prompt.twist:next.twist};setPromptHistory(h=>[{...prompt},...h].slice(0,6));setPrompt(merged);setPromptSpin(n=>n+1);setPromptCopied(false)}
