 function setOrreryFilter(key,value){setPromptFilters(prev=>{const next={...prev,[key]:value};try{localStorage.setItem('palace-orrery-filters',JSON.stringify(next))}catch{}return next})}
 function clearOrreryFilters(){const next={flavour:'all',genre:'all',mood:'all',character:'all',relationship:'all',setting:'all',conflict:'all',difficulty:'all'};setPromptFilters(next);try{localStorage.removeItem('palace-orrery-filters')}catch{}}
 function restorePrompt(item){setPromptHistory(h=>[{...prompt},...h.filter(x=>x.id!==item.id)].slice(0,6));setPrompt(item);setPromptSpin(n=>n+1);setPromptCopied(false)}
 async function copyPrompt(){const text=['Story family: '+(prompt.flavour||'Classic Orbit'),'Genre: '+prompt.genre,'Mood: '+prompt.mood,'Character: '+prompt.character,'Relationship: '+prompt.relationship,'Setting: '+prompt.setting,'Conflict: '+prompt.conflict,'Object: '+prompt.object,'Twist: '+prompt.twist,'Difficulty: '+prompt.difficulty].join('\n');try{await navigator.clipboard.writeText(text);setPromptCopied(true);window.setTimeout(()=>setPromptCopied(false),1800)}catch{setPromptCopied(false)}}
 function bringPromptToDesk(){setTitle(prompt.genre+' — '+prompt.object);setPromptCopied(false);window.setTimeout(()=>document.querySelector('.chic-new-work input')?.focus(),0)}
 function invite(workId){setInviteForm({handle:'',role:'co_writer'});setInviteDialog(workId)} async function submitInvite(){try{await inviteWorkCollaborator(session.user.id,inviteDialog,inviteForm.handle,inviteForm.role);setInviteDialog(null);await load()}catch(e){setError(e.message)}}
