 async function sendRelayInvite(){if(!relayInvite.roomId||!relayInvite.handle.trim())return;try{setRelayBusy('invite');await inviteRelayWriter(relayInvite.roomId,relayInvite.handle);setRelayInvite({roomId:'',handle:''});await load()}catch(e){setError(e.message)}finally{setRelayBusy('')}}
 async function answerRelay(roomId,status){try{setRelayBusy(status+roomId);await respondRelayInvitation(roomId,status);await load()}catch(e){setError(e.message)}finally{setRelayBusy('')}}
 async function changeRelayStatus(roomId,status){try{setRelayBusy(status+roomId);await setRelayRoomStatus(roomId,status);await load()}catch(e){setError(e.message)}finally{setRelayBusy('')}}
 async function passRelay(room){const body=relayTurn.roomId===room.id?relayTurn.body:'';if(!body.trim())return;try{setRelayBusy('turn'+room.id);const result=await submitRelayTurn(room.id,body);setRelayTurn({roomId:'',body:''});await load();if(Number(result?.celestial_points_awarded||0)>0)window.setTimeout(()=>setError(''),100)}catch(e){setError(e.message)}finally{setRelayBusy('')}}
 async function toggleRelayAudience(room){try{setRelayBusy('audience'+room.id);await setRelayAudience(room.id,!room.audience_open);await load()}catch(e){setError(e.message)}finally{setRelayBusy('')}}
