 async function start(e){e.preventDefault();let made=null;try{setActionError('');const roomLabel=thread.kind==='salon'?'Reading Salon':thread.kind==='recommendation'?'Reading Salon':thread.kind==='question'?'Palace Commons':'Palace Commons';made=await createForumThread(session.user.id,thread.title,thread.body,roomLabel);if(thread.kind==='poll'){const choices=pollOptions.map(x=>x.trim()).filter(Boolean);try{await createForumPoll(session.user.id,made.id,thread.title,choices)}catch(pollError){await deleteOwnForumThread(session.user.id,made.id).catch(()=>{});throw pollError}}setThread({title:'',body:'',kind:'discussion',source:''});setPollOptions(['','']);try{localStorage.removeItem('palace-commons-compose')}catch{}await load()}catch(e){setActionError(e.message)}}
