 async function threadPref(item,type,key){try{await setForumThreadPreference(session.user.id,item.id,type,!item[key]);await load()}catch(e){setActionError(e.message)}} async function voteForumPoll(poll,optionId){if(!poll||poll.status!=='open')return;try{setPollBusy(poll.id);await castForumPollVote(session.user.id,poll.id,optionId);await load()}catch(e){setActionError(e.message)}finally{setPollBusy('')}} async function finishForumPoll(poll){try{setPollBusy(poll.id);await closeForumPoll(session.user.id,poll.id);await load()}catch(e){setActionError(e.message)}finally{setPollBusy('')}}
