 const counts={commons:data?.threads.length||0,clubs:data?.clubs.length||0,moonlight:data?.chat.length||0,stars:data?.communityIntroductions?.length||data?.introductions.length||0,invites:data?.clubInvites?.length||0,requests:data?.stewardRequests?.length||0,myRequests:data?.myClubRequests?.filter(x=>x.status==='pending').length||0,highlights:data?.highlights?.length||0};
