 useEffect(()=>{restoredPlaceRef.current='';getChapter(slug,chapterId).then(async d=>{setData(d);if(d){getPalacePraiseState('chapter',d.chapter.id).then(setPraise).catch(()=>{});if(session){try{const[chapterNotes,readerState]=await Promise.all([getReaderNotesForChapter(session.user.id,d.chapter.id),getWorkReaderState(session.user.id,d.work.id)]);setNotes(chapterNotes);const savedPlace=readerState?.progress?.chapter_id===d.chapter.id?Number(readerState.progress.chapter_progress_percent||0):0;setReaderPlace(savedPlace);const readable=d.work.chapters.filter(c=>c.status==='published');const index=Math.max(0,readable.findIndex(c=>c.id===d.chapter.id));const overall=Math.max(5,Math.min(95,Math.round((index/Math.max(1,readable.length))*100)));await recordReadingProgress(session.user.id,d.work.id,d.chapter.id,overall,false,savedPlace)}catch{}}}}).catch(e=>setError(e.message))},[slug,chapterId,session?.user?.id]);
