 useEffect(()=>{if(!data||!session)return;const readable=data.work.chapters.filter(ch=>ch.status==='published');const index=Math.max(0,readable.findIndex(ch=>ch.id===data.chapter.id));const overall=Math.max(5,Math.min(95,Math.round((index/Math.max(1,readable.length))*100)));const savePlace=()=>{const el=chapterTextRef.current;if(!el)return;const top=window.scrollY+el.getBoundingClientRect().top;const anchor=window.scrollY+window.innerHeight*.35;const pct=Math.max(0,Math.min(100,((anchor-top)/Math.max(1,el.offsetHeight))*100));setReaderPlace(pct);try{localStorage.setItem('palace-reading-place:'+data.chapter.id,String(pct))}catch{}if(placeTimerRef.current)window.clearTimeout(placeTimerRef.current);placeTimerRef.current=window.setTimeout(()=>recordReadingProgress(session.user.id,data.work.id,data.chapter.id,overall,false,pct).catch(()=>{}),900)};window.addEventListener('scroll',savePlace,{passive:true});window.addEventListener('pagehide',savePlace);return()=>{window.removeEventListener('scroll',savePlace);window.removeEventListener('pagehide',savePlace);if(placeTimerRef.current)window.clearTimeout(placeTimerRef.current)}},[data?.chapter?.id,session?.user?.id]); useEffect(()=>{document.body.classList.toggle('reader-focus-mode',readerFocus);return()=>document.body.classList.remove('reader-focus-mode')},[readerFocus]);
