function palaceLocalDateTimeValue(iso,offsetMinutes=60){const d=iso?new Date(iso):new Date(Date.now()+offsetMinutes*60000);if(Number.isNaN(d.getTime()))return'';const pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
