      <div className="editor-tool-group" aria-label="Text style"><button type="button" title="Bold" onMouseDown={e=>e.preventDefault()} onClick={()=>exec('bold')}><b>B</b></button><button type="button" title="Italic" onMouseDown={e=>e.preventDefault()} onClick={()=>exec('italic')}><i>I</i></button><button type="button" title="Underline" onMouseDown={e=>e.preventDefault()} onClick={()=>exec('underline')}><u>U</u></button><button type="button" title="Strikethrough" onMouseDown={e=>e.preventDefault()} onClick={()=>exec('strikeThrough')}><s>S</s></button></div>
